def cases():
    return json.loads(json.dumps(CASES))

def prepared(row):
    return [(float(t),float(y),str(a)) for t,y,a in row['parameters']['records'] if t is not None and y is not None and a is not None and math.isfinite(float(t)) and math.isfinite(float(y))]

def mathematical(row, *, diagnostics=False):
    with mp.workdps(70):
        p=mp.mpf(str(row['parameters']['period']));raw=prepared(row);names=list(dict.fromkeys(a for t,y,a in raw));parts=[]
        for name in names:
            data=[(mp.mpf(str(t)),mp.mpf(str(y))) for t,y,a in raw if a==name]
            X=mp.matrix([[1,mp.cos(2*mp.pi*t/p),mp.sin(2*mp.pi*t/p)] for t,y in data]);y=mp.matrix([v for t,v in data]);ones=mp.matrix([1]*len(data))
            parts.append((X,y,ones,len(data)))
        N=sum(n for X,y,ones,n in parts)
        def likelihood(beta,lam):
            rss=mp.mpf(0);logdet=mp.mpf(0)
            for X,y,ones,n in parts:
                r=y-X*beta;total=sum(r);rss+=sum(v*v for v in r)-lam*total**2/(1+n*lam);logdet+=mp.log(1+n*lam)
            return N*mp.log(rss/N)+logdet
        def solve(lam):
            A=mp.matrix(3,3);z=mp.matrix(3,1)
            for X,y,ones,n in parts:
                sx=X.T*ones;sy=sum(y);weight=lam/(1+n*lam)
                A+=X.T*X-weight*sx*sx.T;z+=X.T*y-weight*sx*sy
            beta=mp.lu_solve(A,z);return likelihood(beta,lam),beta
        # Independent numerical differentiation, not the production score.
        def score(lam):return mp.diff(lambda q:solve(q)[0],lam)
        grid=[mp.mpf(0),*[mp.mpf(10)**(mp.mpf(i)/10) for i in range(-60,81)]]
        roots=[];previous=score(grid[0])
        for a,b in zip(grid,grid[1:]):
            current=score(b)
            if previous<0<current:roots.append(mp.findroot(score,(a,b),solver='anderson',tol=mp.mpf('1e-55')))
            previous=current
        lam=min([mp.mpf(0),*roots],key=lambda q:solve(q)[0]);objective,beta=solve(lam)
        parameters=[*beta] if lam==0 else [*beta,lam]
        def negative_log_likelihood(*args):return likelihood(mp.matrix(args[:3]),mp.mpf(0) if lam==0 else args[3])/2
        hessian=mp.matrix([[mp.diff(negative_log_likelihood,parameters,tuple(int(k==i)+int(k==j) for k in range(len(parameters)))) for j in range(len(parameters))] for i in range(len(parameters))])
        covariance=hessian**-1;bg=mp.matrix(beta[1:]);cov_bg=mp.matrix([[covariance[i,j] for j in [1,2]] for i in [1,2]])
        W=(bg.T*cov_bg**-1*bg)[0];probability=mp.exp(-W/2)
        M,b,g=beta;amplitude=mp.sqrt(b*b+g*g);phase=(mp.atan2(g,b)%(2*mp.pi))*p/(2*mp.pi)
        answer=[float(v) for v in [M,amplitude,phase,p,mp.nan,probability,mp.nan,mp.nan]]
        if diagnostics:return answer,{'lambda':float(lam),'objective':float(objective),'beta':[float(v) for v in beta],'W':float(W),'covariance':[[float(covariance[i,j]) for j in range(len(parameters))] for i in range(len(parameters))]}
        return answer

def native_core(row, *, published=False):
    data=prepared(row);names=list(dict.fromkeys(a for t,y,a in data));p=row['parameters']['period']
    vector=lambda xs:'c('+','.join(format(v,'.17g') for v in xs)+')'
    fit_code='''
        native<-nlme::lme(y~cosine+sine,random=~1|subject,data=d,method='ML',
          control=nlme::lmeControl(tolerance=1e-12,msTol=1e-12,msMaxIter=1000,maxIter=1000));
        lam<-as.numeric(nlme::VarCorr(native)[1,'Variance'])/native$sigma^2;beta<-as.numeric(nlme::fixef(native));
    ''' if published else '''
        grid<-c(0,10^seq(-6,8,by=.13));scores<-sapply(grid,function(q)solve_model(q)$score);roots<-numeric();
        for(i in seq_len(length(grid)-1))if(scores[i]<0 && scores[i+1]>0)roots<-c(roots,uniroot(function(q)solve_model(q)$score,c(grid[i],grid[i+1]),tol=1e-12)$root);
        choices<-c(0,roots);lam<-choices[which.min(sapply(choices,function(q)solve_model(q)$objective))];beta<-solve_model(lam)$beta;
    '''
    return f'''local({{
        t<-{vector([t for t,y,a in data])};y<-{vector([y for t,y,a in data])};subject<-factor({vector([names.index(a) for t,y,a in data])});
        cosine<-cos(2*pi*t/{p});sine<-sin(2*pi*t/{p});d<-data.frame(y,cosine,sine,subject);X<-cbind(1,cosine,sine);N<-length(y);parts<-split(seq_along(y),subject);
        solve_model<-function(lam){{
            A<-matrix(0,3,3);z<-rep(0,3);logdet<-0;
            for(idx in parts){{Xi<-X[idx,,drop=FALSE];yi<-y[idx];n<-length(idx);sx<-colSums(Xi);w<-lam/(1+n*lam);
                A<-A+crossprod(Xi)-w*tcrossprod(sx);z<-z+drop(crossprod(Xi,yi))-w*sx*sum(yi);logdet<-logdet+log1p(n*lam)}};
            beta<-solve(A,z);rss<-0;derivative<-0;
            for(idx in parts){{r<-y[idx]-drop(X[idx,,drop=FALSE]%*%beta);n<-length(idx);rss<-rss+sum(r*r)-lam*sum(r)^2/(1+n*lam);derivative<-derivative-sum(r)^2/(1+n*lam)^2}};
            list(beta=beta,rss=rss,objective=N*log(rss/N)+logdet,score=N*derivative/rss+sum(sapply(parts,function(idx)length(idx)/(1+length(idx)*lam))))
        }};
        {fit_code}
        rss<-0;first<-0;second<-0;A<-matrix(0,3,3);cross<-rep(0,3);detsecond<-0;
        for(idx in parts){{Xi<-X[idx,,drop=FALSE];r<-y[idx]-drop(Xi%*%beta);n<-length(idx);sx<-colSums(Xi);sr<-sum(r);den<-1+n*lam;
            rss<-rss+sum(r*r)-lam*sr^2/den;first<-first-sr^2/den^2;second<-second+2*n*sr^2/den^3;
            A<-A+crossprod(Xi)-lam*tcrossprod(sx)/den;cross<-cross+sx*sr/den^2;detsecond<-detsecond+n^2/den^2}};
        information<-matrix(0,4,4);information[1:3,1:3]<-N*A/rss;information[1:3,4]<-N*cross/rss;information[4,1:3]<-N*cross/rss;
        information[4,4]<-N/2*(second/rss-(first/rss)^2)-detsecond/2;
        covariance<-solve(information);W<-drop(t(beta[2:3])%*%solve(covariance[2:3,2:3])%*%beta[2:3]);probability<-pchisq(W,2,lower.tail=FALSE);
        c(beta[1],sqrt(sum(beta[2:3]^2)),(atan2(beta[3],beta[2])%%(2*pi))*{p}/(2*pi),{p},NA_real_,probability,NA_real_,NA_real_)
    }})'''

def native_query(row):
    code=native_core(row)
    return code.replace('covariance<-solve(information);W<-',
        'covariance<-if(lam==0) solve(information[1:3,1:3]) else solve(information);W<-')

def production(row):
    import pandas as pd
    from PyFLASH.stats_extra import _mixed_cosinor
    data=pd.DataFrame(prepared(row),columns=['_t','_v','animal']);answer=_mixed_cosinor(data,'animal',row['parameters']['period'])
    assert set(answer)==set(FIELDS)
    return [answer[k] for k in FIELDS]

def check_identity():
    fixture=json.loads(FIXTURE.read_text(encoding='utf-8'))
    if hashlib.sha256(Path(__file__).read_text(encoding='utf-8').encode()).hexdigest()!=fixture['reference_code_sha256']:
        raise ValueError('Frozen mixed-rhythm reference code changed.')
    current=cases()
    if current!=[{k:r[k] for k in c} for c,r in zip(current,fixture['rows'],strict=True)]:
        raise ValueError('Frozen mixed-rhythm inputs changed.')
    queries=[{'key':r['key'],'code':native_query(r)} for r in current]+[{'key':r['key'],'code':zero_noise_native_query(r)} for r in zero_noise_cases()]
    if queries!=[{k:r[k] for k in q} for q,r in zip(queries,fixture['native']['rows'],strict=True)]:
        raise ValueError('Frozen mixed-rhythm native expressions changed.')
    return fixture,queries

def execute(output):
    fixture,queries=check_identity()
    result=execute_queries(queries,output,name='mixed-rhythm-independent-ML-boundary')
    for key in ['R','webR','wasm_sha256']:
        if result[key]!=fixture['native'][key]:raise ValueError('Native mixed-rhythm runtime changed: '+key)
    return result


