def zero_noise_native_query(row):
    records=row['parameters']['records'];names=list(dict.fromkeys(r[2] for r in records));N=len(records)
    vector=lambda xs:'c('+','.join(format(float(v),'.17g') for v in xs)+')'
    return f'''local({{
        y<-{vector([r[1] for r in records])};cosine<-{vector([r[3] for r in records])};sine<-{vector([r[4] for r in records])};subject<-{vector([names.index(r[2]) for r in records])};
        mu<-mean(2+2*unique(subject))+cosine+.5*sine;r<-y-mu;parts<-split(seq_along(y),subject);
        loglik<-function(epsilon){{
            logdet<-0;quadratic<-0;
            for(idx in parts){{n<-length(idx);ri<-r[idx];logdet<-logdet+(n-1)*log(epsilon)+log(epsilon+n);
                quadratic<-quadratic+sum((ri-mean(ri))^2)/epsilon+n*mean(ri)^2/(epsilon+n)}};
            -.5*({N}*log(2*pi)+logdet+quadratic)
        }};
        sapply(c(1e-2,1e-4,1e-6,1e-8),loglik)
    }})'''
